  e_skeleton: {"tier": 3, "zh": "骷髏劍客", "en": "Skeleton Swordsman", "bio": {"zh": "死在斷崖下的劍客，骨頭還記得怎麼出劍。", "en": "A swordsman who died under the cliff; his bones still remember how to strike."}, "habitat": {"zh": "山洞、古廟與斷崖", "en": "Caves, old temples and cliffs"}},
