  e_bronzeman: {"tier": 3, "zh": "銅人", "en": "Bronze Guardian", "bio": {"zh": "寺裡試武用的銅人，機關一開就擺出拳架。", "en": "A temple bronze man for testing fighters; trip its mechanism and it takes a stance."}, "habitat": {"zh": "山洞、古廟與斷崖", "en": "Caves, old temples and cliffs"}},
