  e_daoist: {"tier": 3, "zh": "妖道", "en": "Rogue Daoist", "bio": {"zh": "畫符招鬼的妖道，長鬚飄飄，一臉仙氣，滿肚子壞水。", "en": "A rogue Daoist who draws charms to summon ghosts: flowing beard, saintly face, a bellyful of mischief."}, "habitat": {"zh": "山洞、古廟與斷崖", "en": "Caves, old temples and cliffs"}},
  e_ironcrab: {"tier": 4, "zh": "鐵甲蟹", "en": "Iron Crab", "bio": {"zh": "殼像鐵甲一樣灰亮的老螃蟹，躲在沼澤的爛泥裡。", "en": "An old crab whose shell shines grey like armour; it lurks in the marsh mud."}, "habitat": {"zh": "古墓、沼澤與高塔", "en": "Old tombs, marshes and towers"}},
  e_ghosthornet: {"tier": 4, "zh": "鬼面蜂", "en": "Ghostface Hornet", "bio": {"zh": "背上花紋像一張鬼臉的毒蜂，養在古墓的蜂窩裡。", "en": "A poison hornet whose back is patterned like a ghost face; it nests in old tombs."}, "habitat": {"zh": "古墓、沼澤與高塔", "en": "Old tombs, marshes and towers"}},
  e_goldcentipede: {"tier": 4, "zh": "金頭蜈蚣", "en": "Golden Centipede", "bio": {"zh": "金黃色的大蜈蚣，練毒的人拿牠泡酒。", "en": "A great golden centipede that poison-masters steep in wine."}, "habitat": {"zh": "古墓、沼澤與高塔", "en": "Old tombs, marshes and towers"}},
