  e_bloodthug: {"tier": 4, "zh": "血刀門打手", "en": "Blood Saber Thug", "bio": {"zh": "血刀門雇來的打手，紅衣黑巾，下手不留情。", "en": "A thug hired by the Blood Saber Sect, red clothes and black scarf, merciless."}, "habitat": {"zh": "古墓、沼澤與高塔", "en": "Old tombs, marshes and towers"}},
